<script setup lang="ts">
import { useRouteFunction } from '@/composable/useRouteFunction';
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { getProjectWorkById, ProjectType, PROJECT_WORKS } from '@/constants/projects';
import useTranslation from '@/composable/useTranslation';
import { useI18n } from 'vue-i18n';
import VSvgComponent from '@/components/VSvgComponent.vue';
import { mdiOpenInNew, mdiPlay } from '@mdi/js';
const { t } = useI18n();

useRouteFunction();
const { getTranslatedDescription } = useTranslation();

const route = useRoute();

// Считаем от параметра маршрута, а не разово при монтировании: при переходе
// к соседнему проекту компонент переиспользуется и заново не монтируется
const currentProject = computed<ProjectType | undefined>(() => getProjectWorkById(String(route.params.id)));

const details = computed(() => currentProject.value?.details);

const currentIndex = computed(() => PROJECT_WORKS.findIndex(p => p.id === currentProject.value?.id));

const prevProject = computed<ProjectType | undefined>(() => {
    if (currentIndex.value === -1 || PROJECT_WORKS.length < 2) return undefined;
    const index = (currentIndex.value - 1 + PROJECT_WORKS.length) % PROJECT_WORKS.length;
    return PROJECT_WORKS[index];
});

const nextProject = computed<ProjectType | undefined>(() => {
    if (currentIndex.value === -1 || PROJECT_WORKS.length < 2) return undefined;
    const index = (currentIndex.value + 1) % PROJECT_WORKS.length;
    return PROJECT_WORKS[index];
});

const stackList = computed(() => details.value?.stack?.split(',').map(s => s.trim()) ?? []);

const playingVideo = reactive<Record<number, boolean>>({});

const lightboxIndex = ref(-1);

const imageCount = computed(() => currentProject.value?.media?.length ?? 0);

const lightboxItem = computed(() => (
    lightboxIndex.value >= 0 ? currentProject.value?.media?.[lightboxIndex.value] : undefined
));

const openLightbox = (index: number) => {
    lightboxIndex.value = index;
};

const closeLightbox = () => {
    lightboxIndex.value = -1;
};

const shiftLightbox = (direction: number) => {
    if (!imageCount.value) {
        return;
    }

    lightboxIndex.value = (lightboxIndex.value + direction + imageCount.value) % imageCount.value;
};

const onLightboxKey = (event: KeyboardEvent) => {
    if (lightboxIndex.value < 0) {
        return;
    }

    if (event.key === 'Escape') {
        closeLightbox();
    } else if (event.key === 'ArrowLeft') {
        shiftLightbox(-1);
    } else if (event.key === 'ArrowRight') {
        shiftLightbox(1);
    }
};

// Соседний проект — своя галерея: сбрасываем просмотрщик и запущенные видео
watch(() => route.params.id, () => {
    closeLightbox();
    Object.keys(playingVideo).forEach((key) => delete playingVideo[Number(key)]);
});

onMounted(() => {
    window.addEventListener('keydown', onLightboxKey);
});

onUnmounted(() => {
    window.removeEventListener('keydown', onLightboxKey);
});
</script>

<template>
    <div class="text-[13px] text-soft dark:text-soft-dark mb-5">
        <router-link
            to="/works/"
            class="hover:underline hover:text-ink dark:hover:text-ink-dark transition-colors"
        >
            {{ t("general.works") }}
        </router-link>
        <span class="mx-1.5 opacity-60">/</span>
        <span class="text-ink dark:text-ink-dark font-bold">{{ currentProject?.name }}</span>
    </div>

    <div class="flex flex-wrap items-center gap-3 mb-1.5">
        <p class="text-[28px] sm:text-[32px] font-bold font-serif tracking-tight">{{ currentProject?.name }}</p>
        <span
            v-if="currentProject?.year"
            class="py-1 px-2.5 rounded-md bg-tagbg dark:bg-imgbg-dark text-soft dark:text-soft-dark text-xs font-bold"
        >
            {{ currentProject.year }}
        </span>
    </div>
    <p v-if="details?.role" class="text-sm text-soft dark:text-soft-dark mb-4">
        {{ details.role }}
    </p>

    <p class="text-[16px] leading-[1.75] text-soft dark:text-soft-dark mb-7">
        {{ getTranslatedDescription(currentProject?.description) }}
    </p>

    <div
        v-if="stackList.length || details?.website"
        class="
        flex flex-col sm:flex-row sm:items-center gap-5 sm:gap-10
        mb-9 p-5 rounded-2xl
        bg-card dark:bg-card-dark
        border border-black/10 dark:border-white/[.14]
        "
    >
        <div v-if="stackList.length" class="flex-1">
            <span class="block text-[11px] font-bold uppercase tracking-[.04em] text-soft dark:text-soft-dark mb-2">
                {{ t('general.stack') }}
            </span>
            <div class="flex flex-wrap gap-1.5">
                <span
                    v-for="tech in stackList"
                    :key="tech"
                    class="text-xs font-semibold py-1 px-2.5 rounded-md bg-mint dark:bg-mint-dark text-onmint dark:text-white"
                >
                    {{ tech }}
                </span>
            </div>
        </div>
        <div v-if="details?.website" class="flex flex-wrap gap-2">
            <a
                v-for="(link, index) in details.website"
                :key="index"
                :href="link.url"
                target="_blank"
                rel="noopener noreferrer"
                class="
                flex items-center gap-1.5
                py-2 px-4 rounded-[10px]
                text-sm font-bold
                bg-mint dark:bg-mint-dark
                text-onmint
                border border-mintline dark:border-mintline-dark
                shadow-[0_2px_0_#7cc79c] dark:shadow-[0_2px_0_#3d9478]
                hover:brightness-95
                transition
                focus-visible:ring-2 focus-visible:ring-mintline dark:focus-visible:ring-mintline-dark focus-visible:outline-none
                "
            >
                {{ details.website.length > 1 ? (link.label || `${t('general.code')} ${index + 1}`) : t('general.code') }}
                <VSvgComponent
                    :icon="mdiOpenInNew"
                    width="14px"
                    height="14px"
                    class="fill-onmint"
                />
            </a>
        </div>
    </div>

    <div
        v-if="currentProject?.media?.length"
        class="grid gap-4 sm:grid-cols-2"
    >
        <div
            v-for="(item, key) in currentProject?.media"
            :key="key"
            class="
            relative
            w-full aspect-video rounded-[14px] overflow-hidden
            border border-black/10 dark:border-white/[.14]
            shadow-[0_1px_2px_rgba(0,0,0,0.04)]
            transition-all duration-300
            hover:-translate-y-1 hover:shadow-[0_14px_28px_rgba(0,0,0,0.12)]
            "
            :class="key === 0 || item.type === 'video' ? 'sm:col-span-2' : ''"
        >
            <button
                v-if="item.type === 'image'"
                type="button"
                class="block w-full h-full cursor-zoom-in focus-visible:ring-2 focus-visible:ring-mintline dark:focus-visible:ring-mintline-dark focus-visible:outline-none"
                :aria-label="`${t('general.openImage')}: ${currentProject?.name}`"
                @click="openLightbox(key)"
            >
                <img
                    class="w-full h-full object-cover"
                    :src="item.src"
                    :alt="`${currentProject?.name} — ${key + 1}`"
                />
            </button>
            <template v-else>
                <video
                    v-if="playingVideo[key]"
                    class="w-full h-full object-cover"
                    :src="item.src"
                    :poster="item.poster"
                    controls
                    autoplay
                ></video>
                <button
                    v-else
                    type="button"
                    class="group/play relative block w-full h-full focus-visible:ring-2 focus-visible:ring-mintline dark:focus-visible:ring-mintline-dark focus-visible:outline-none"
                    :aria-label="`${t('general.playVideo')}: ${currentProject?.name}`"
                    @click="playingVideo[key] = true"
                >
                    <img
                        class="w-full h-full object-cover"
                        :src="item.poster"
                        :alt="`${currentProject?.name} — video`"
                    />
                    <span class="absolute inset-0 flex items-center justify-center bg-black/25 transition-colors group-hover/play:bg-black/35">
                        <span class="flex items-center justify-center w-14 h-14 rounded-full bg-mint dark:bg-mint-dark border border-mintline dark:border-mintline-dark shadow-[0_2px_0_#7cc79c] dark:shadow-[0_2px_0_#3d9478] transition-transform group-hover/play:scale-105">
                            <VSvgComponent
                                :icon="mdiPlay"
                                width="26px"
                                height="26px"
                                class="fill-onmint translate-x-0.5"
                            />
                        </span>
                    </span>
                </button>
            </template>
        </div>
    </div>

    <!-- Просмотрщик выносится в body: внутри экрана ноутбука он был бы заперт
         в его плоскости, а фото нужно показать во всю страницу -->
    <teleport to="body">
        <div
            v-if="lightboxItem"
            class="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 p-4 sm:p-10"
            role="dialog"
            aria-modal="true"
            @click.self="closeLightbox"
        >
            <img
                :src="lightboxItem.type === 'video' ? lightboxItem.poster : lightboxItem.src"
                :alt="`${currentProject?.name} — ${lightboxIndex + 1}`"
                class="max-w-full max-h-full object-contain rounded-lg select-none"
            />

            <button
                type="button"
                class="absolute top-4 right-4 w-10 h-10 rounded-full bg-white/15 text-white text-xl leading-none flex items-center justify-center transition hover:bg-white/25 focus-visible:ring-2 focus-visible:ring-white focus-visible:outline-none"
                :aria-label="t('general.close')"
                @click="closeLightbox"
            >×</button>

            <template v-if="imageCount > 1">
                <button
                    type="button"
                    class="absolute left-3 sm:left-6 top-1/2 -translate-y-1/2 w-11 h-11 rounded-full bg-white/15 text-white text-2xl leading-none flex items-center justify-center transition hover:bg-white/25 focus-visible:ring-2 focus-visible:ring-white focus-visible:outline-none"
                    :aria-label="t('general.prevImage')"
                    @click="shiftLightbox(-1)"
                >‹</button>
                <button
                    type="button"
                    class="absolute right-3 sm:right-6 top-1/2 -translate-y-1/2 w-11 h-11 rounded-full bg-white/15 text-white text-2xl leading-none flex items-center justify-center transition hover:bg-white/25 focus-visible:ring-2 focus-visible:ring-white focus-visible:outline-none"
                    :aria-label="t('general.nextImage')"
                    @click="shiftLightbox(1)"
                >›</button>
                <span class="absolute bottom-5 left-1/2 -translate-x-1/2 text-sm text-white/70 tabular-nums">
                    {{ lightboxIndex + 1 }} / {{ imageCount }}
                </span>
            </template>
        </div>
    </teleport>

    <!-- Внутри экрана ноутбука страница скроллится сама, поэтому переключение проектов
         прилипает к нижней кромке дисплея и всегда под рукой -->
    <div
        v-if="prevProject || nextProject"
        class="
        grid sm:grid-cols-2 gap-4 mt-10 pt-6 pb-1
        border-t border-black/10 dark:border-white/[.14]
        md:sticky md:bottom-0 md:z-10
        md:bg-card/95 md:dark:bg-card-dark/95 md:backdrop-blur
        "
    >
        <router-link
            v-if="prevProject"
            :to="prevProject.to"
            class="
            group flex items-center gap-3
            p-4 rounded-2xl
            bg-card dark:bg-card-dark
            border border-black/10 dark:border-white/[.14]
            transition-all
            hover:-translate-y-0.5 hover:border-mintline/60 dark:hover:border-mintline-dark/60 hover:shadow-[0_10px_20px_rgba(0,0,0,0.08)]
            focus-visible:ring-2 focus-visible:ring-mintline dark:focus-visible:ring-mintline-dark focus-visible:outline-none
            "
        >
            <span
                aria-hidden="true"
                class="text-lg text-soft dark:text-soft-dark transition-transform group-hover:-translate-x-0.5"
            >←</span>
            <span class="flex flex-col">
                <span class="text-[11px] font-bold uppercase tracking-[.04em] text-soft dark:text-soft-dark">
                    {{ t('general.prevProject') }}
                </span>
                <span class="font-bold">{{ prevProject.name }}</span>
            </span>
        </router-link>
        <span v-else class="hidden sm:block"></span>
        <router-link
            v-if="nextProject"
            :to="nextProject.to"
            class="
            group flex items-center justify-end gap-3 text-right
            p-4 rounded-2xl
            bg-card dark:bg-card-dark
            border border-black/10 dark:border-white/[.14]
            transition-all
            hover:-translate-y-0.5 hover:border-mintline/60 dark:hover:border-mintline-dark/60 hover:shadow-[0_10px_20px_rgba(0,0,0,0.08)]
            focus-visible:ring-2 focus-visible:ring-mintline dark:focus-visible:ring-mintline-dark focus-visible:outline-none
            "
        >
            <span class="flex flex-col items-end">
                <span class="text-[11px] font-bold uppercase tracking-[.04em] text-soft dark:text-soft-dark">
                    {{ t('general.nextProject') }}
                </span>
                <span class="font-bold">{{ nextProject.name }}</span>
            </span>
            <span
                aria-hidden="true"
                class="text-lg text-soft dark:text-soft-dark transition-transform group-hover:translate-x-0.5"
            >→</span>
        </router-link>
    </div>
</template>
